 10	// trailFindingsJSONInstructions is the trail-mode output contract. Reviewers
 11	// and the judge end with this JSON line so posting reads their findings
 12	// structurally instead of interpreting prose. The example line must parse
 13	// with splitTrailJSON; a test enforces that.
 14	const trailFindingsJSONInstructions = `Final line (required, read by a program):
 15	End your output with exactly one line holding only this JSON object, with no code fence and nothing after it:
 16	{"summary":"one-sentence verdict","comments":[{"severity":"high","body":"bug; impact; fix","location":{"granularity":"line","file_path":"path/to/file.go","start_line":42}}]}
 17	- Add one comment per actionable finding reported above, with the same severity: high, medium, or low.
 18	- location.granularity is line (with start_line), range (with start_line and end_line), file, or whole_change.
 19	- If nothing is actionable, use an empty array: "comments":[].
 20	- This line is required even where other instructions say to output nothing else.`
 21	
 22	// maxTrailJSONLines bounds the backward scan for a pretty-printed JSON block.
 23	const maxTrailJSONLines = 200
 24	
 25	// TrailComment is one finding in the trail JSON contract.
 26	type TrailComment struct {
 27		Severity   string        `json:"severity"`
 28		Confidence *float64      `json:"confidence,omitempty"`
 29		Body       string        `json:"body"`
 30		Location   TrailLocation `json:"location"`
 31	}
 32	
 33	// TrailLocation anchors a TrailComment to the change.
 34	type TrailLocation struct {
 35		Granularity  string `json:"granularity"`
 36		FilePath     string `json:"file_path,omitempty"`
 37		StartLine    int    `json:"start_line,omitempty"`
 38		EndLine      int    `json:"end_line,omitempty"`
 39		SelectedText string `json:"selected_text,omitempty"`
 40	}
 41	
 42	// TrailReport is what a trail-mode run posts: structured comments from
 43	// reviews that honored the JSON contract, and the prose, with any contract
 44	// line removed, of those that did not. At least one of the two is set.
 45	type TrailReport struct {
 46		Comments []TrailComment
 47		Prose    string
 48	}
 49	
 50	// trailReportFor decides what a trail-mode run posts. It returns post=false
 51	// only when the JSON contract reports no findings and nothing in the prose
 52	// contradicts that; every malformed or contradictory case posts, so a
 53	// misbehaving model costs an extra finding rather than a lost one. A posted
 54	// report is empty only when the output had nothing readable. When a judge
 55	// ran, its verdict decides: it is asked to drop unsupported claims.
 56	func trailReportFor(summary reviewtypes.RunSummary, aggregateOutput string) (TrailReport, bool) {
 57		if verdict := strings.TrimSpace(aggregateOutput); verdict != "" {
 58			prose, comments, ok := splitTrailJSON(verdict)
 59			if !contractCoversProse(prose, comments, ok) {
 60				if prose == "" {
 61					// A JSON-only reply without a summary has no prose of its own.
 62					prose = combinedReviewNarratives(usableAgentRuns(summary))
 63				}
 64				return TrailReport{Prose: prose}, true
 65			}
 66			return TrailReport{Comments: comments}, len(comments) > 0
 67		}
 68		var merged []TrailComment
 69		var unstructured []reviewtypes.AgentRun
 70		for _, run := range usableAgentRuns(summary) {
 71			prose, comments, ok := splitTrailJSON(reportText(run.Buffer))
 72			if !contractCoversProse(prose, comments, ok) {
 73				unstructured = append(unstructured, run)
 74				continue
 75			}
 76			merged = append(merged, comments...)
 77		}
 78		report := TrailReport{Comments: merged, Prose: combinedReviewNarratives(unstructured)}
 79		return report, len(merged) > 0 || len(unstructured) > 0
 80	}
 81	
 82	// contractCoversProse reports whether a valid contract can be posted in place
 83	// of its prose: the prose reports no finding the comments leave out. The
 84	// prose normally repeats every comment, so it is posted instead of, not
 85	// alongside, an incomplete contract.
 86	func contractCoversProse(prose string, comments []TrailComment, ok bool) bool {
 87		if !ok {
 88			return false
 89		}
 90		if len(comments) == 0 {
 91			return !proseReportsFindings(prose)
 92		}
 93		return markedFindingCount(prose) <= len(comments)
 94	}
 95	
 96	// markedFindingCount counts the lines, list items included, that open with a
 97	// severity marker: the finding shape the output format asks for.
 98	func markedFindingCount(prose string) int {
 99		count := 0
100		for _, line := range strings.Split(prose, "\n") {
101			trimmed := strings.TrimSpace(line)
102			if item, ok := ListItemText(trimmed); ok {
103				trimmed = item
104			}
105			if StartsWithSeverityMarker(trimmed) {
106				count++
107			}
108		}
109		return count
110	}
111	
112	// reportText returns a reviewer's report: the last stretch of text between
113	// tool calls that ends with a valid contract line, or "" if none does. It is
114	// found by the contract line rather than by position, so a tool call after
115	// the report does not hide it, and earlier exploration narration, whose
116	// bullets ("I'll check:\n- retry.go") are not findings, is left out. A tool
117	// call inside a message, where the next text continues it as a delta, is not
118	// a boundary. A stretch holding only the contract line also takes the stretch
119	// before it, so a report written before a final tool call is still checked
120	// against the line.
121	func reportText(buf []reviewtypes.Event) string {
122		end := len(buf)
123		for i := len(buf) - 1; i >= -1; i-- {
124			if i >= 0 && !isTextBoundary(buf, i) {
125				continue
126			}
127			text := joinAssistantText(buf[i+1 : end])
128			prose, payload, found := splitTrailJSONPayload(text)
129			if _, ok := decodeTrailComments(payload["comments"]); !found || !ok {
130				end = i
131				continue
132			}
133			if prose == "" && i >= 0 {
134				start := i - 1
135				for start >= 0 && !isTextBoundary(buf, start) {
136					start--
137				}
138				if before := joinAssistantText(buf[start+1 : i]); strings.TrimSpace(before) != "" {
139					return before + "\n\n" + text
140				}
141			}
142			return text
143		}
144		return ""
145	}
146	
147	// isTextBoundary reports whether buf[i] is a tool call that separates two
148	// stretches of text rather than interrupting a message.
149	func isTextBoundary(buf []reviewtypes.Event, i int) bool {
150		_, ok := buf[i].(reviewtypes.ToolCall)
151		return ok && !continuesMessage(buf[i+1:])
152	}
153	
154	// continuesMessage reports whether the first text in buf continues the
155	// message before it.
156	func continuesMessage(buf []reviewtypes.Event) bool {
157		for _, ev := range buf {
158			if at, ok := ev.(reviewtypes.AssistantText); ok {
159				return at.Delta
160			}
161		}
162		return false
163	}
164	
165	// splitTrailJSON separates a trailing contract-shaped JSON object (one line,
166	// a fenced block, or a pretty-printed block, with a "summary" or "comments"
167	// key) from the prose before it, so a malformed contract is never posted as
168	// finding text. Other trailing JSON, such as a config snippet quoted as
169	// evidence, stays in the prose. A JSON-only reply contributes its summary as
170	// the prose instead. ok reports a valid contract: a "comments" array.
171	// Entries without a body are dropped.
172	func splitTrailJSON(text string) (prose string, comments []TrailComment, ok bool) {
173		prose, payload, found := splitTrailJSONPayload(text)
174		if !found {
175			return prose, nil, false
176		}
177		if prose == "" {
178			var summary string
179			if json.Unmarshal(payload["summary"], &summary) == nil {
180				prose = strings.TrimSpace(summary)
181			}
182		}
183		comments, ok = decodeTrailComments(payload["comments"])
184		return prose, comments, ok
185	}
186	
187	// splitTrailJSONPayload finds a trailing contract-shaped JSON object and
188	// returns the prose before it and its decoded keys. found is false, with
189	// the whole text as prose, when there is none.
190	func splitTrailJSONPayload(text string) (prose string, payload map[string]json.RawMessage, found bool) {
191		text = strings.TrimSpace(text)
192		lines := strings.Split(text, "\n")
193		end := len(lines)
194		fenced := end > 1 && strings.TrimSpace(lines[end-1]) == "```"
195		if fenced {
196			end--
197		}
198		for start := end - 1; start >= 0 && start >= end-maxTrailJSONLines; start-- {
199			if !strings.HasPrefix(strings.TrimSpace(lines[start]), "{") {
200				continue
201			}
202			payload = nil
203			if err := json.Unmarshal([]byte(strings.Join(lines[start:end], "\n")), &payload); err != nil {
204				continue
205			}
206			_, hasSummary := payload["summary"]
207			_, hasComments := payload["comments"]
208			if !hasSummary && !hasComments {
209				break
210			}
211			proseEnd := start
212			if fenced && proseEnd > 0 && strings.HasPrefix(strings.TrimSpace(lines[proseEnd-1]), "```") {
213				proseEnd--
214			}
215			return strings.TrimSpace(strings.Join(lines[:proseEnd], "\n")), payload, true
216		}
217		return text, nil, false
218	}
219	
220	func decodeTrailComments(raw json.RawMessage) ([]TrailComment, bool) {
221		if !strings.HasPrefix(strings.TrimSpace(string(raw)), "[") {
222			return nil, false
223		}
224		var decoded []TrailComment
225		if err := json.Unmarshal(raw, &decoded); err != nil {
226			return nil, false
227		}
228		comments := []TrailComment{}
229		for _, comment := range decoded {
230			if strings.TrimSpace(comment.Body) != "" {
231				comments = append(comments, comment)
232			}
233		}
234		return comments, true
235	}
236	
237	// stripTrailJSON removes a valid trailing contract line for display. Only a
238	// run that asked for the line has one; elsewhere a trailing JSON block is the
239	// reviewer's own text and stays.
240	func stripTrailJSON(text string, trailFindingsJSON bool) string {
241		if !trailFindingsJSON {
242			return text
243		}
244		if prose, _, ok := splitTrailJSON(text); ok {
245			return prose
246		}
247		return text
248	}
249	
250	// proseReportsFindings reports whether prose contradicts an empty comments
251	// array: a list item, severity marker, or feedback label such as "Nits:" at
252	// any indentation, or a verdict, labeled or not, that itself says there is
253	// feedback. These are the shapes the output format asks for, so a clean
254	// review has none of them.
255	func proseReportsFindings(prose string) bool {
256		for _, line := range strings.Split(prose, "\n") {
257			trimmed := strings.TrimSpace(line)
258			if _, ok := ListItemText(trimmed); ok {
259				return true
260			}
261			lower := strings.ToLower(trimMarkdownEmphasis(trimmed))
262			if after, found := strings.CutPrefix(lower, "verdict"); found {
263				lower = trimMarkdownEmphasis(strings.TrimLeft(after, ":-—– "))
264			}
265			if StartsWithSeverityMarker(lower) {
266				return true
267			}
268			for _, prefix := range []string{
269				"request changes", "request_changes", "changes requested", "approve with nits",
270				"needs changes", "needs work", "changes needed",
271				"nits:", "issues:", "concerns:", "suggestions:", "findings:", "problems:", "blocking:",
272			} {
273				if strings.HasPrefix(lower, prefix) {
274					return true
275				}
276			}
277		}
278		return false
279	}
280	
281	func trimMarkdownEmphasis(s string) string {
282		return strings.TrimLeft(s, "#>*_` ")
283	}
284	
285	// StartsWithSeverityMarker reports whether line, after leading Markdown
286	// emphasis, opens with a severity tag: bracketed ("[high]"), delimited
287	// ("high —", "p2:"), closed by emphasis ("**High** ..."), or alone (a "### High"
288	// heading). A word that merely starts with a marker ("Highlights") is not one.
289	func StartsWithSeverityMarker(line string) bool {
290		lower := strings.ToLower(trimMarkdownEmphasis(strings.TrimSpace(line)))
291		for _, marker := range []string{"critical", "high", "medium", "low", "p0", "p1", "p2", "p3", "nit"} {
292			if strings.HasPrefix(lower, "["+marker+"]") {
293				return true
294			}
295			rest, found := strings.CutPrefix(lower, marker)
296			if !found {
297				continue
298			}
299			if strings.TrimSpace(rest) == "" {
300				return true
301			}
302			for _, suffix := range []string{" —", " –", " -", ":", "*", "_"} {
303				if strings.HasPrefix(rest, suffix) {
304					return true
305				}
306			}
307		}
308		return false
309	}
310	
311	// ListItemText returns the text of a Markdown list item ("- ", "* ", "+ ",
312	// "• ", "1. ", "1) ") and whether trimmed, a line without surrounding space,
313	// is one.
314	func ListItemText(trimmed string) (string, bool) {
315		for _, bullet := range []string{"- ", "* ", "+ ", "• "} {
316			if item, found := strings.CutPrefix(trimmed, bullet); found {
317				return strings.TrimSpace(item), true
318			}
319		}
320		digits := len(trimmed) - len(strings.TrimLeft(trimmed, "0123456789"))
321		if digits == 0 {
322			return "", false
323		}
324		for _, delim := range []string{". ", ") "} {
325			if item, found := strings.CutPrefix(trimmed[digits:], delim); found {
326				return strings.TrimSpace(item), true
327			}
328		}
329		return "", false
330	}

