// SplitProseFindings splits prose into its top-level findings: list items and
// lines that open with a severity marker, each with the lines that continue
// it. A line holding only a severity ("### High", "**Low:**") groups the
// findings below it rather than being one; text under it that is not a list
// item is a finding, and a placeholder such as "None." is not. Trail posting
// counts findings with this and the bridge posts them, so both agree on what
// a finding is.
func SplitProseFindings(prose string) []ProseFinding {
	var findings []ProseFinding
	var current strings.Builder
	group := ""
