	ref := path + ":" + strconv.Itoa(line)
	for _, comment := range comments {
		if strings.Contains(comment.Body, ref) {
			return true
		}
		loc := comment.Location
		if samePath(loc.FilePath, path) && loc.StartLine > 0 && line >= loc.StartLine && line <= max(loc.EndLine, loc.StartLine) {
			return true
		}
	}
	return false
}

// samePath reports whether two paths name the same file, allowing one to be
// a shorter suffix of the other ("retry.go" and "internal/retry.go").
func samePath(a, b string) bool {
	a, b = strings.TrimPrefix(a, "./"), strings.TrimPrefix(b, "./")
	if a == "" || b == "" {
		return false
	}
	return a == b || strings.HasSuffix(a, "/"+b) || strings.HasSuffix(b, "/"+a)
}

// reportText returns a reviewer's report: the last stretch of text between
// tool calls that ends with a valid contract line, or "" if none does. It is
// found by the contract line rather than by position, so a tool call after
// the report does not hide it, and earlier exploration narration, whose
// bullets ("I'll check:\\n- retry.go") are not findings, is left out. A stretch
// holding only the contract line also takes the latest earlier stretch that
// reports findings by more than bullets, so a report written before the final
// tool calls is still checked against the line.
func reportText(buf []reviewtypes.Event) string {
	stretches := textStretches(buf)
	for i := len(stretches) - 1; i >= 0; i-- {
		prose, payload, found := splitTrailJSONPayload(stretches[i])
		if _, ok := decodeTrailComments(payload["comments"]); !found || !ok {
			continue
		}
		if prose == "" {
			for j := i - 1; j >= 0; j-- {
				if proseReportsMarkedFindings(stretches[j]) {
					return stretches[j] + "\\n\\n" + stretches[i]
				}
			}
		}
		return stretches[i]
	}
	return ""
}

// textStretches splits buf's assistant text at tool calls. A tool call inside
// a message, where the next text continues it as a delta, does not split it.
func textStretches(buf []reviewtypes.Event) []string {
	var stretches []string
	var segment []reviewtypes.Event
	afterToolCall := false
	for _, ev := range buf {
		switch ev := ev.(type) {
		case reviewtypes.ToolCall:
			afterToolCall = true
		case reviewtypes.AssistantText:
			if afterToolCall && !ev.Delta && len(segment) > 0 {
				stretches = append(stretches, joinAssistantText(segment))
				segment = nil
			}
			afterToolCall = false
			segment = append(segment, ev)
		}
	}
	if len(segment) > 0 {
		stretches = append(stretches, joinAssistantText(segment))
	}
	return stretches
}

