// unindented lines that open with a severity marker, each with the lines that
// continue it. A line holding only a severity label ("### High", "**Low:**")
// sets the severity of the findings below it rather than being one, and text
// under it that is not a list item is a finding too. Any other heading ends
// that, and placeholders such as "None." are skipped.
func SplitProseFindings(prose string) []ProseFinding {
	var findings []ProseFinding
	var current strings.Builder
	group := ""
	flush := func() {
		text := strings.TrimSpace(current.String())
		current.Reset()
		if text == "" {
			return
		}
		severity := leadingSeverity(text)
		if severity == "" {
			severity = group
		}
		findings = append(findings, ProseFinding{Text: text, Severity: severity})
	}
	for _, line := range strings.Split(strings.TrimSpace(prose), "\\n") {
		if label := severityLabel(line); label != "" {
			flush()
			group = label
			continue
		}
		if isUnindented(line) && strings.HasPrefix(line, "#") {
			flush()
			group = ""
			continue
		}
		text := listItemOrLine(line)
		if item, ok := topLevelListItemText(line); ok || (isUnindented(line) && leadingSeverity(line) != "") {
			flush()
			if !ok {
				item = text
			}
			if !isNoFindingsText(item) {
				current.WriteString(item)
			}
			continue
		}
		if current.Len() == 0 {
			if group == "" || isNoFindingsText(text) {
				continue
			}
		} else {
			current.WriteByte('\\n')
		}
		current.WriteString(line)
	}
	flush()
	return findings
}

func topLevelListItemText(line string) (string, bool) {
	if !isUnindented(line) {
		return "", false
	}
	item, ok := listItemText(strings.TrimSpace(line))
	return item, ok && item != ""
}

